// Prepare data chunks for embedding
const data = $input.item.json.data;
const dataType = $input.item.json.data_type;
const showName = $input.item.json.show_name;

let chunks = [];

if (dataType === 'fandom_wiki') {
  // Process character data
  if (data.character_name) {
    chunks.push({
      id: `char_${showName}_${data.character_name}`.replace(/\s+/g, '_').toLowerCase(),
      text: `Character: ${data.character_name}\n\nBio: ${Array.isArray(data.character_bio) ? data.character_bio.join(' ') : data.character_bio}\n\nRelationships: ${data.relationships || 'N/A'}`,
      metadata: {
        type: 'character',
        show_name: showName,
        character_name: data.character_name,
        source: 'fandom_wiki',
        scraped_at: data.scraped_at
      }
    });
  }

  // Process episode data
  if (data.episode_title) {
    chunks.push({
      id: `ep_${showName}_${data.episode_number || data.episode_title}`.replace(/\s+/g, '_').toLowerCase(),
      text: `Episode: ${data.episode_title}\n\nNumber: ${data.episode_number}\n\nSummary: ${Array.isArray(data.episode_summary) ? data.episode_summary.join(' ') : data.episode_summary}\n\nTranscript: ${data.transcript || 'N/A'}`,
      metadata: {
        type: 'episode',
        show_name: showName,
        episode_title: data.episode_title,
        episode_number: data.episode_number,
        air_date: data.air_date,
        source: 'fandom_wiki',
        scraped_at: data.scraped_at
      }
    });
  }
} else if (dataType === 'perplexity_enrichment') {
  // Process Perplexity enriched data
  chunks.push({
    id: `enriched_${showName}_${data.topic}`.replace(/\s+/g, '_').toLowerCase(),
    text: `Topic: ${data.topic}\n\nAnalysis:\n${data.comprehensive_analysis}`,
    metadata: {
      type: 'enriched_analysis',
      show_name: showName,
      topic: data.topic,
      enrichment_type: data.enrichment_type,
      queries_processed: data.queries_processed,
      citations: data.all_citations,
      source: 'perplexity_ai',
      enriched_at: data.enriched_at
    }
  });
}

return chunks.map(chunk => ({ json: chunk }));

// Summarize indexing results
const allItems = $input.all();

let summary = {
  success: true,
  vectors_indexed: allItems.length,
  namespace: $('Extract Parameters').item.json.namespace,
  show_name: $('Extract Parameters').item.json.show_name,
  data_type: $('Extract Parameters').item.json.data_type,
  indexed_at: new Date().toISOString(),
  vector_ids: allItems.map(item => item.json.id || 'unknown')
};

return { json: summary };
